#!/usr/bin/env python3
"""Generate the fixed DCM-32 preview fixture (not a product document).

Requires python-pptx 1.0.2 and Pillow 13.0.0. No Office installation, external
assets, user documents, network requests, or Windows registration are used.
The committed PPTX is the input to qualification; tests do not regenerate it.
"""

from datetime import datetime, timezone
import hashlib
from io import BytesIO
import json
from pathlib import Path
import zipfile

from PIL import Image, ImageDraw
import PIL
import pptx
from pptx import Presentation
from pptx.dml.color import RGBColor
from pptx.enum.text import PP_ALIGN
from pptx.util import Inches, Pt


ROOT = Path(__file__).resolve().parent
DECK_PATH = ROOT / "dcm32-slides.pptx"
MANIFEST_PATH = ROOT / "dcm32-slides.manifest.json"
TEAL = (20, 125, 146)
ORANGE = (232, 123, 53)
INK = (28, 43, 59)
FIXED_DATE = datetime(2026, 11, 14, 0, 0, 0, tzinfo=timezone.utc)


def bridge_image():
    """An exact geometric media oracle, deliberately without font dependence."""
    image = Image.new("RGB", (360, 200), (235, 246, 248))
    draw = ImageDraw.Draw(image)
    draw.rectangle((0, 136, 359, 199), fill=TEAL)
    draw.rectangle((22, 102, 337, 119), fill=ORANGE)
    draw.rectangle((67, 115, 87, 175), fill=INK)
    draw.rectangle((272, 115, 292, 175), fill=INK)
    draw.line((35, 101, 78, 42, 282, 42, 325, 101), fill=INK, width=8)
    for x in (78, 112, 146, 180, 214, 248, 282):
        draw.line((x, 43, x, 101), fill=INK, width=4)
    draw.rectangle((0, 176, 359, 182), fill=(98, 192, 201))
    stream = BytesIO()
    image.save(stream, format="PNG", optimize=False, compress_level=9)
    return stream.getvalue()


def text(slide, value, x, y, width, height, size, bold=False, color=INK):
    shape = slide.shapes.add_textbox(Inches(x), Inches(y), Inches(width), Inches(height))
    frame = shape.text_frame
    frame.margin_left = frame.margin_right = 0
    frame.margin_top = frame.margin_bottom = 0
    frame.word_wrap = True
    paragraph = frame.paragraphs[0]
    paragraph.alignment = PP_ALIGN.LEFT
    run = paragraph.add_run()
    run.text = value
    run.font.name = "Arial"
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.color.rgb = RGBColor(*color)
    return shape


def generate():
    presentation = Presentation()
    presentation.slide_width = Inches(12)
    presentation.slide_height = Inches(6.75)
    core = presentation.core_properties
    core.title = "DCM-32 representative PPTX preview fixture"
    core.subject = "Synthetic two-slide text, image and table qualification"
    core.author = "Flowverse qualification tooling"
    core.last_modified_by = "Flowverse qualification tooling"
    core.created = core.modified = FIXED_DATE
    core.revision = 1
    core.keywords = "synthetic fixture; DCM QuickSort; DCM-32"
    core.comments = "No real inspection or payment data. Tests pin the generated bytes."

    first = presentation.slides.add_slide(presentation.slide_layouts[6])
    text(first, "Bridge Inspection", 0.6, 0.45, 10.8, 0.65, 32, True)
    text(first, "September 2026", 0.6, 1.2, 10.8, 0.5, 22)
    media = bridge_image()
    picture = first.shapes.add_picture(BytesIO(media), Inches(0.6), Inches(2.1), width=Inches(6))
    picture.name = "Bridge inspection image"
    picture._element.nvPicPr.cNvPr.set("descr", "Synthetic bridge illustration with teal water and orange deck")
    text(first, "Representative image", 7.1, 2.35, 4.1, 0.55, 22, True)
    text(first, "Text and embedded picture\nPreview qualification only", 7.1, 3.05, 4.1, 1.4, 20)
    text(first, "DCM-32 / SLIDE 1", 0.6, 6.05, 10.8, 0.35, 14, color=TEAL)

    second = presentation.slides.add_slide(presentation.slide_layouts[6])
    text(second, "Payments", 0.6, 0.45, 10.8, 0.65, 32, True)
    text(second, "Synthetic amounts for preview verification", 0.6, 1.2, 10.8, 0.5, 20)
    table = second.shapes.add_table(3, 2, Inches(0.6), Inches(2.1), Inches(10.8), Inches(2.7)).table
    table.columns[0].width = Inches(6.8)
    table.columns[1].width = Inches(4)
    values = (("Scheme", "Amount"), ("Bridge", "125000"), ("Road", "86000"))
    for row_index, row in enumerate(values):
        for col_index, value in enumerate(row):
            cell = table.cell(row_index, col_index)
            cell.text = value
            cell.margin_left = Inches(0.2)
            cell.margin_top = Inches(0.14)
            cell.fill.solid()
            cell.fill.fore_color.rgb = RGBColor(*(TEAL if row_index == 0 else (235, 246, 248)))
            for paragraph in cell.text_frame.paragraphs:
                for run in paragraph.runs:
                    run.font.name = "Arial"
                    run.font.size = Pt(24)
                    run.font.bold = row_index == 0
                    run.font.color.rgb = RGBColor(*((255, 255, 255) if row_index == 0 else INK))
    text(second, "DCM-32 / SLIDE 2", 0.6, 6.05, 10.8, 0.35, 14, color=TEAL)

    raw = BytesIO()
    presentation.save(raw)
    # python-pptx writes current ZIP timestamps. Canonical ordering/metadata makes
    # identical source and dependency versions produce identical fixture bytes.
    fixed = BytesIO()
    with zipfile.ZipFile(raw) as source, zipfile.ZipFile(fixed, "w") as target:
        for name in sorted(source.namelist()):
            member = zipfile.ZipInfo(name, (2026, 11, 14, 0, 0, 0))
            member.compress_type = zipfile.ZIP_DEFLATED
            member.create_system = 3
            member.external_attr = 0o100644 << 16
            target.writestr(member, source.read(name), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    data = fixed.getvalue()
    DECK_PATH.write_bytes(data)
    manifest = {
        "schema_version": 1,
        "feature": "DCM-32",
        "file": DECK_PATH.name,
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "generator": Path(__file__).name,
        "dependencies": {"python-pptx": pptx.__version__, "Pillow": PIL.__version__},
        "synthetic": True,
        "slide_count": 2,
        "slide_size_inches": [12, 6.75],
        "slides": [
            {"number": 1, "required_text": ["Bridge Inspection", "September 2026"],
             "image": {"part": "ppt/media/image1.png", "size": [360, 200],
                       "sha256": hashlib.sha256(media).hexdigest(),
                       "marker_rgb": {"teal": list(TEAL), "orange": list(ORANGE)}}},
            {"number": 2, "required_text": ["Payments", "Scheme", "125000", "Road", "86000"],
             "table_rows": [list(row) for row in values]},
        ],
        "scope": "Two representative static slides; this is not a general PowerPoint fidelity corpus.",
    }
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"path": str(DECK_PATH), "bytes": len(data), "sha256": manifest["sha256"]}))


if __name__ == "__main__":
    generate()
